import{_ as e,b as i,c as n,g as t}from"./chunks/framework.86O3EbG5.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"articles/ai/books/ai-modern-approach-homework/8.md","filePath":"articles/ai/books/ai-modern-approach-homework/8.md"}'),l={name:"articles/ai/books/ai-modern-approach-homework/8.md"};function p(x,a,o,r,m,s){return i(),n("div",null,[...a[0]||(a[0]=[t('<h2 id="将以下自然语句翻译成一阶逻辑公式-定义必要的谓词、函数、常量" tabindex="-1">将以下自然语句翻译成一阶逻辑公式（定义必要的谓词、函数、常量）：</h2><ul><li>“所有数学家都是逻辑学家。”</li><li>“有些教授喜欢所有的学生。”</li><li>“每个城市都有一个大学。”</li><li>“张三的母亲是李四。” （可以使用 MotherOf(x,y) 表示 x 是 y 的母亲）</li></ul><h2 id="解释量词作用域、自由变量、绑定变量。判断以下公式是否合法" tabindex="-1">解释量词作用域、自由变量、绑定变量。判断以下公式是否合法：</h2><ul><li>(a) ∀x P(x) → Q(x)</li><li>(b) ∃x (P(x) ∧ ∀x Q(x))</li><li>(c) ∀x ∃y R(x,y) → ∃y R(y,x)</li></ul><p>并指出其中变量的出现。</p><h2 id="给定知识库" tabindex="-1">给定知识库：</h2><p>• ∀x (Cat(x) → Mammal(x)) • Cat(Mittens) • ∀x (Mammal(x) → Animal(x)) 使用前向链接推导出 Animal(Mittens)，写出每一步的合一替换。</p><h2 id="计算以下表达式对的最一般合一器-如果存在" tabindex="-1">计算以下表达式对的最一般合一器（如果存在）：</h2><ul><li>P(f(x, g(y)), h(z)) 与 P(f(a, g(b)), h(c))</li><li>Q(x, y, f(x, a)) 与 Q(g(z), z, f(g(z), a))</li><li>R(x, f(x, b)) 与 R(g(y), f(g(y), y)) （是否存在合一？若存在，给出MGU）</li></ul><h2 id="用反向链接证明-animal-mittens-是否可以从题目3的知识库中推出。画出反向链接的与或树-并标出合一步骤。" tabindex="-1">用反向链接证明 Animal(Mittens) 是否可以从题目3的知识库中推出。画出反向链接的与或树，并标出合一步骤。</h2><h2 id="将以下一阶逻辑公式转换为cnf-合取范式-为归结做准备-注意先消去蕴含、移动否定符号、skolem化" tabindex="-1">将以下一阶逻辑公式转换为CNF（合取范式），为归结做准备（注意先消去蕴含、移动否定符号、Skolem化）：</h2><p><code>∀x ∃y (P(x) → (Q(y) ∧ ¬R(x,y))) ∧ ¬∀x S(x)</code></p><h2 id="家族关系建模" tabindex="-1">家族关系建模</h2><p>定义谓词 Parent(x,y), Male(x), Female(x)。</p><p>写出定义“父亲”、“母亲”、“兄弟”、“姐妹”、“祖先”的一阶逻辑公理。</p><p>从以下事实：Parent(王强, 王丽), Parent(王强, 王明), Male(王强), Female(王丽), Male(王明)，使用前向链接推导出“王丽和王明是兄妹”。写出推导过程（合一及规则触发）。</p><h2 id="归纳证明" tabindex="-1">归纳证明</h2><p>用自然数归纳公理：</p><p>∀P [ (P(0) ∧ ∀n (P(n) → P(s(n))) ) → ∀n P(n) ]</p><p>证明：∀n (sum(0,n) = n) 和 ∀n ∀m (sum(s(n), m) = s(sum(n, m))) 可推导出 ∀n sum(n, 0) = n。 （仅需写出归纳步骤，无需完全形式化）</p><h2 id="学术会议论文审稿系统" tabindex="-1">学术会议论文审稿系统</h2><p>设计一个小型一阶逻辑知识库，用于判断一篇论文是否被接收。规则包括：</p><p>如果论文有创新性且没有重大错误，则接收。</p><p>如果评审人总数至少为3，且至少2人推荐接收，则接收。</p><p>如果出现抄袭，则拒收。 定义所需的谓词和常量（例如 HasInnovation(p), HasPlagiarism(p), ReviewerRecommend(r,p) 等）。 给定具体事实（如某篇论文有创新性，无抄袭，3个评审人中2人推荐），写出查询公理，并用一阶逻辑前向链接或反向链接推理该论文是否接收。</p><h2 id="比较命题化与直接合一推理" tabindex="-1">比较命题化与直接合一推理</h2><p>假设你有一个包含量词的大知识库（例如关于所有自然数的事实）。如果使用命题化（将每个实例像 Nat(0), Nat(1) ... 无限展开），显然不可行。说明合一算法（如在前向链接中）如何无需展开所有实例就能匹配规则。举一个简单例子：规则 ∀x (Human(x) → Mortal(x))，事实 Human(Socrates)。解释合一算法如何将变量 x 绑定为 Socrates。</p>',27)])])}const c=e(l,[["render",p]]);export{h as __pageData,c as default};
